package EmployeeManagementSystem.controller;
import EmployeeManagementSystem.entity.EmployeeTransportRequest; import EmployeeManagementSystem.security.jwt.JwtUtil; import EmployeeManagementSystem.repository.EmployeeRepository; import EmployeeManagementSystem.service.EmployeeTransportRequestService; import EmployeeManagementSystem.service.RequestScopeService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/transport-requests") public class EmployeeTransportRequestController{
 private final EmployeeTransportRequestService service; private final JwtUtil jwt; private final EmployeeRepository employees; private final RequestScopeService scope; public EmployeeTransportRequestController(EmployeeTransportRequestService s,JwtUtil j,EmployeeRepository e,RequestScopeService requestScope){service=s;jwt=j;employees=e;scope=requestScope;}
 private String tok(String a){if(a==null||!a.startsWith("Bearer "))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Authentication required.");return a.substring(7);} private String user(String a){return jwt.extractUsername(tok(a));} private String role(String a){String r=jwt.extractRole(tok(a));return r==null?"":r.replace("ROLE_","").toUpperCase();} private boolean mgmt(String r){return Set.of("ADMIN","HR","MANAGER").contains(r);}
 @GetMapping("/my") public List<EmployeeTransportRequest> my(@RequestHeader("Authorization")String a){return service.my(user(a));}
 @GetMapping public List<EmployeeTransportRequest> all(@RequestHeader("Authorization")String a){String currentRole=role(a);if(!mgmt(currentRole))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Management access required.");return scope.visibleTo(currentRole,user(a),service.all());}
 @PostMapping public EmployeeTransportRequest create(@RequestHeader("Authorization")String a,@RequestBody EmployeeTransportRequest x){String u=user(a);String n=employees.findByRegisterEmployee_UserId(u).map(e->e.getFullName()).orElse(u);try{return service.create(x,u,n);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
 @PatchMapping("/{id}/review") public EmployeeTransportRequest review(@RequestHeader("Authorization")String a,@PathVariable Long id,@RequestBody Map<String,Object>b){String currentRole=role(a);if(!mgmt(currentRole))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Management access required.");scope.assertCanReviewById(currentRole,user(a),service.all(),id);try{return service.review(id,String.valueOf(b.get("status")),String.valueOf(b.getOrDefault("comment","")),user(a),String.valueOf(b.getOrDefault("assignedTo","")));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}}
}
